"""Social platform frontend pages — FeedPage and FollowersPage."""
from __future__ import annotations

# ---------------------------------------------------------------------------
# FeedPage.tsx — Social feed with likes, hashtags, and trending sidebar
# ---------------------------------------------------------------------------

FEED_PAGE_TSX = '''\
// FeedPage.tsx — Auto-generated by AetherOS p05_frontend (social domain)
import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Heart, MessageCircle, Hash } from 'lucide-react'

const API = import.meta.env.VITE_API_URL ?? ''
const auth = () => ({ Authorization: `Bearer ${localStorage.getItem('token') ?? ''}` })

function relTime(iso: string): string {
  const d = Math.floor((Date.now() - new Date(iso).getTime()) / 1000)
  if (d < 60) return `${d}s`
  if (d < 3600) return `${Math.floor(d / 60)}m`
  if (d < 86400) return `${Math.floor(d / 3600)}h`
  return `${Math.floor(d / 86400)}d`
}

interface Post {
  id: string
  author_id: string
  author_username: string
  author_display_name?: string
  content: string
  like_count: number
  comment_count: number
  is_liked: boolean
  hashtags: string[]
  created_at: string
}

interface Hashtag {
  tag: string
  post_count: number
}

function PostCard({ post }: { post: Post }) {
  const qc = useQueryClient()
  const toggle = useMutation({
    mutationFn: async () => {
      const method = post.is_liked ? 'DELETE' : 'POST'
      const res = await fetch(`${API}/api/social/posts/${post.id}/like`, { method, headers: auth() })
      if (!res.ok) throw new Error('Like failed')
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ['feed'] }),
    onError: (e) => console.error('like toggle:', e),
  })

  return (
    <div className="rounded-xl border border-border bg-card p-4 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex items-center gap-3 mb-3">
        <span className="flex h-9 w-9 items-center justify-center rounded-full bg-accent text-sm font-bold text-primary">
          {(post.author_display_name ?? post.author_username)[0].toUpperCase()}
        </span>
        <div>
          <p className="text-sm font-semibold text-foreground">
            {post.author_display_name ?? post.author_username}
          </p>
          <p className="text-xs text-muted-foreground">
            @{post.author_username} · {relTime(post.created_at)}
          </p>
        </div>
      </div>
      <p className="text-sm text-foreground mb-3 leading-relaxed">{post.content}</p>
      {post.hashtags.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-3">
          {post.hashtags.map(tag => (
            <span
              key={tag}
              className="inline-flex items-center gap-0.5 rounded-full bg-accent px-2 py-0.5 text-xs font-medium text-primary"
            >
              <Hash className="h-3 w-3" />{tag}
            </span>
          ))}
        </div>
      )}
      <div className="flex items-center gap-5 pt-2 border-t border-border">
        <button
          onClick={() => toggle.mutate()}
          disabled={toggle.isPending}
          className={`flex items-center gap-1.5 text-xs font-medium transition-colors ${
            post.is_liked ? 'text-destructive hover:text-destructive' : 'text-muted-foreground hover:text-destructive'
          }`}
        >
          <Heart className={`h-4 w-4 ${post.is_liked ? 'fill-current' : ''}`} />
          {post.like_count}
        </button>
        <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <MessageCircle className="h-4 w-4" />
          {post.comment_count}
        </span>
      </div>
    </div>
  )
}

export default function FeedPage() {
  const { data: posts = [], isLoading } = useQuery<Post[]>({
    queryKey: ['feed'],
    queryFn: async () => {
      const res = await fetch(`${API}/api/social/feed`, { headers: auth() })
      if (!res.ok) throw new Error('Feed fetch failed')
      return res.json()
    },
  })

  const { data: trending = [] } = useQuery<Hashtag[]>({
    queryKey: ['trending-hashtags'],
    queryFn: async () => {
      const res = await fetch(`${API}/api/social/hashtags/trending`, { headers: auth() })
      if (!res.ok) return []
      return res.json()
    },
  })

  return (
    <div className="mx-auto max-w-5xl px-4 py-6">
      <h1 className="text-2xl font-bold text-foreground mb-6">Feed</h1>
      <div className="flex gap-6">
        <div className="flex-1 space-y-4">
          {isLoading ? (
            Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="h-40 rounded-xl bg-muted animate-pulse" />
            ))
          ) : posts.length === 0 ? (
            <div className="rounded-xl border border-dashed border-input p-12 text-center">
              <p className="text-muted-foreground text-sm">
                No posts yet. Follow some users to see their posts here.
              </p>
            </div>
          ) : (
            posts.map(post => <PostCard key={post.id} post={post} />)
          )}
        </div>
        {trending.length > 0 && (
          <aside className="hidden lg:block w-64 shrink-0">
            <div className="rounded-xl border border-border bg-card p-4 shadow-sm sticky top-6">
              <h2 className="text-sm font-semibold text-foreground mb-3">Trending</h2>
              <div className="space-y-2">
                {trending.slice(0, 10).map(h => (
                  <div key={h.tag} className="flex items-center justify-between">
                    <span className="flex items-center gap-1 text-sm text-primary font-medium">
                      <Hash className="h-3.5 w-3.5" />{h.tag}
                    </span>
                    <span className="text-xs text-muted-foreground">{h.post_count}</span>
                  </div>
                ))}
              </div>
            </div>
          </aside>
        )}
      </div>
    </div>
  )
}
'''

# ---------------------------------------------------------------------------
# FollowersPage.tsx — Followers / Following tabs with follow toggle
# ---------------------------------------------------------------------------

FOLLOWERS_PAGE_TSX = '''\
// FollowersPage.tsx — Auto-generated by AetherOS p05_frontend (social domain)
import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { UserPlus, UserMinus } from 'lucide-react'

const API = import.meta.env.VITE_API_URL ?? ''
const auth = () => ({ Authorization: `Bearer ${localStorage.getItem('token') ?? ''}` })

interface SocialUser {
  user_id: string
  username: string
  display_name?: string
  is_following: boolean
}

function UserCard({ user }: { user: SocialUser }) {
  const qc = useQueryClient()
  const toggle = useMutation({
    mutationFn: async () => {
      const method = user.is_following ? 'DELETE' : 'POST'
      const res = await fetch(`${API}/api/social/users/${user.user_id}/follow`, {
        method, headers: auth(),
      })
      if (!res.ok) throw new Error('Follow toggle failed')
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ['connections'] }),
    onError: (e) => console.error('follow toggle:', e),
  })

  return (
    <div className="flex items-center justify-between rounded-xl border border-border bg-card p-4 shadow-sm">
      <div className="flex items-center gap-3">
        <span className="flex h-10 w-10 items-center justify-center rounded-full bg-accent text-sm font-bold text-primary">
          {(user.display_name ?? user.username)[0].toUpperCase()}
        </span>
        <div>
          <p className="text-sm font-semibold text-foreground">
            {user.display_name ?? user.username}
          </p>
          <p className="text-xs text-muted-foreground">@{user.username}</p>
        </div>
      </div>
      <button
        onClick={() => toggle.mutate()}
        disabled={toggle.isPending}
        className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
          user.is_following
            ? 'bg-muted text-foreground hover:bg-muted'
            : 'bg-primary text-primary-foreground hover:opacity-90'
        }`}
      >
        {user.is_following
          ? <UserMinus className="h-3.5 w-3.5" />
          : <UserPlus className="h-3.5 w-3.5" />}
        {user.is_following ? 'Unfollow' : 'Follow'}
      </button>
    </div>
  )
}

export default function FollowersPage() {
  const [tab, setTab] = useState<'followers' | 'following'>('followers')
  const userId = localStorage.getItem('user_id') ?? 'me'

  const { data: users = [], isLoading } = useQuery<SocialUser[]>({
    queryKey: ['connections', tab, userId],
    queryFn: async () => {
      const res = await fetch(`${API}/api/social/users/${userId}/${tab}`, { headers: auth() })
      if (!res.ok) return []
      return res.json()
    },
  })

  return (
    <div className="mx-auto max-w-2xl px-4 py-6">
      <h1 className="text-2xl font-bold text-foreground mb-6">Connections</h1>
      <div className="flex gap-1 rounded-xl bg-muted p-1 mb-6">
        {(['followers', 'following'] as const).map(t => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={`flex-1 rounded-lg px-4 py-2 text-sm font-medium capitalize transition-colors ${
              tab === t
                ? 'bg-card text-foreground shadow-sm'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            {t}
          </button>
        ))}
      </div>
      <div className="space-y-3">
        {isLoading ? (
          Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="h-20 rounded-xl bg-muted animate-pulse" />
          ))
        ) : users.length === 0 ? (
          <div className="rounded-xl border border-dashed border-input p-12 text-center">
            <p className="text-muted-foreground text-sm">No {tab} yet.</p>
          </div>
        ) : (
          users.map(u => <UserCard key={u.user_id} user={u} />)
        )}
      </div>
    </div>
  )
}
'''
